from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

s=s.replace('<title>3DLite v3.99.1 LiteTrace Fast Mode</title>', '<title>3DLite v3.99.2 LiteTrace Fast Telemetry</title>')
s=s.replace("window.ThreeDLiteVersion='3.99.1';", "window.ThreeDLiteVersion='3.99.2';")

anchor="""  window.__3DLiteLiteTraceFast3991=true;\n  window.ThreeDLiteLiteTraceFast3991=Object.freeze({\n    version:'3.99.1',\n    preset:LiteTraceFastPreset3991,\n    resolveSettings:resolveLiteTraceFastSettings3991,\n    getLastStats:()=>LiteTraceFastRuntime3991.lastStats?{...LiteTraceFastRuntime3991.lastStats}:null\n  });\n"""
if anchor not in s: raise SystemExit('LiteTrace Fast API anchor missing')
telemetry=anchor+"""\n  const LiteTraceFastTelemetry3992={\n    version:'3.99.2', schema:1, history:[], last:null,\n    finishJob(job){\n      if(!job) return null;\n      const fast=job.liteTraceFast&&typeof job.liteTraceFast==='object'?job.liteTraceFast:null;\n      if(!fast) return null;\n      const width=Math.max(1,Number(job.width)||1), height=Math.max(1,Number(job.height)||1);\n      const elapsedMs=Math.max(0,Number(job.elapsedMs)||0), completedPixels=Math.max(0,Number(job.completedPixels)||0);\n      const rayBudget=Math.max(0,Number(fast.rayBudget)||0), sampleBudget=Math.max(0,Number(fast.sampleBudget)||0);\n      const entry={schema:1,version:'3.99.2',renderer:'litetrace',mode:'fast',jobId:job.id||null,status:job.status||'unknown',\n        width,height,elapsedMs,completedPixels,megapixels:(width*height)/1000000,pixelsPerMs:elapsedMs>0?completedPixels/elapsedMs:0,\n        raysPerMs:elapsedMs>0?rayBudget/elapsedMs:0,samplesPerMs:elapsedMs>0?sampleBudget/elapsedMs:0,\n        spp:Math.max(1,Number(fast.spp)||1),maxDepth:Math.max(1,Number(fast.maxDepth)||1),rayBudget,sampleBudget,\n        hitCount:Math.max(0,Number(fast.hitCount)||0),missCount:Math.max(0,Number(fast.missCount)||0),primaryRays:Math.max(0,Number(fast.primaryRays)||0),\n        secondaryRays:Math.max(0,Number(fast.secondaryRays)||0),shadowRays:Math.max(0,Number(fast.shadowRays)||0),\n        reflectionRays:Math.max(0,Number(fast.reflectionRays)||0),refractionRays:Math.max(0,Number(fast.refractionRays)||0),\n        terminatedPaths:Math.max(0,Number(fast.terminatedPaths)||0),reflectionCap:Math.max(0,Number(fast.reflectionCap)||0),\n        shadowRayCap:Math.max(0,Number(fast.shadowRayCap)||0),maxSecondaryRays:Math.max(0,Number(fast.maxSecondaryRays)||0),\n        maxShadowRays:Math.max(0,Number(fast.maxShadowRays)||0),denoiseStrength:Number(fast.denoiseStrength)||0,finishedAt:Number(job.finishedAt)||performance.now()};\n      entry.hitRate=(entry.hitCount+entry.missCount)>0?entry.hitCount/(entry.hitCount+entry.missCount):0;\n      entry.secondaryShare=entry.rayBudget>0?entry.secondaryRays/entry.rayBudget:0; entry.shadowShare=entry.rayBudget>0?entry.shadowRays/entry.rayBudget:0;\n      entry.reflectionShare=entry.rayBudget>0?entry.reflectionRays/entry.rayBudget:0; entry.refractionShare=entry.rayBudget>0?entry.refractionRays/entry.rayBudget:0;\n      this.last=entry; this.history.push(entry); if(this.history.length>24)this.history.splice(0,this.history.length-24);\n      try{if(window.ThreeDLiteL3NAdaptiveRender3990&&typeof window.ThreeDLiteL3NAdaptiveRender3990.observe==='function')\n        window.ThreeDLiteL3NAdaptiveRender3990.observe({renderer:'litetrace-fast',renderTimeMs:elapsedMs,rays:rayBudget,samples:sampleBudget,qualityGain:0,noise:0,efficiency:elapsedMs>0?completedPixels/elapsedMs:0,metadata:{liteTraceFast:{...entry}}});\n      }catch(e){console.warn('[3DLite LiteTrace Fast Telemetry] adaptive observe',e);}\n      return {...entry};\n    },\n    getLast(){return this.last?{...this.last}:null;}, getHistory(){return this.history.map(x=>({...x}));}, reset(){this.history.length=0;this.last=null;return true;}\n  };\n  window.__3DLiteLiteTraceFastTelemetry3992=true;\n  window.ThreeDLiteLiteTraceFastTelemetry3992=LiteTraceFastTelemetry3992;\n"""
s=s.replace(anchor,telemetry,1)

old="""      LiteTraceFastRuntime3991.lastStats=fastStats;\n      job.liteTraceFast=fastStats;\n      job.rayBudget=fastStats.rayBudget;\n      job.sampleBudget=fastStats.sampleBudget;\n"""
new="""      LiteTraceFastRuntime3991.lastStats=fastStats;\n      job.liteTraceFast={...fastStats};\n      job.rayBudget=fastStats.rayBudget;\n      job.sampleBudget=fastStats.sampleBudget;\n      try{\n        if(window.ThreeDLiteLiteTraceFastTelemetry3992&&typeof window.ThreeDLiteLiteTraceFastTelemetry3992.finishJob==='function'){\n          const telemetryJob={...job,status:'complete',finishedAt:performance.now()};\n          telemetryJob.elapsedMs=Math.max(0,telemetryJob.finishedAt-(Number(job.startedAt)||telemetryJob.finishedAt));\n          window.ThreeDLiteLiteTraceFastTelemetry3992.finishJob(telemetryJob);\n        }\n      }catch(e){console.warn('[3DLite LiteTrace Fast Telemetry] finishJob',e);}\n"""
if old not in s: raise SystemExit('fastStats job anchor missing')
s=s.replace(old,new,1)

for required in ["window.ThreeDLiteVersion='3.99.2';",'ThreeDLiteLiteTraceFastTelemetry3992','renderer:\'litetrace-fast\'','raysPerMs','samplesPerMs']:
    if required not in s: raise SystemExit('missing '+required)
p.write_text(s,encoding='utf-8')
print('patched v3.99.2 LiteTrace Fast telemetry wiring')
